        fillRule="evenodd"
      />
    </svg>
  );
};

export default function App() {
  return (
    <div className="flex gap-4 items-center">
      <Button color="success" endContent={<CameraIcon />}>
        Take a photo
      </Button>
      <Button color="danger" startContent={<UserIcon />} variant="bordered">
        Delete user
      </Button>
    </div>
  );
}

